(()=>{
'use strict';
const ions=[{s:'Na',z:11,g:1,ion:'Na⁺',shells:2,e:10,r:78},{s:'Mg',z:12,g:2,ion:'Mg²⁺',shells:2,e:10,r:73},{s:'Al',z:13,g:13,ion:'Al³⁺',shells:2,e:10,r:68},{s:'Si',z:14,g:14,ion:null},{s:'P',z:15,g:15,ion:'P³⁻',shells:3,e:18,r:174},{s:'S',z:16,g:16,ion:'S²⁻',shells:3,e:18,r:166},{s:'Cl',z:17,g:17,ion:'Cl⁻',shells:3,e:18,r:158},{s:'Ar',z:18,g:18,ion:'Ar',shells:3,e:18,r:150,neutral:true}];
class IonicRadius{constructor(){this.index=0}get current(){return ions[this.index]}next(){this.index=Math.min(7,this.index+1)}reset(){this.index=0}get plotted(){return ions.slice(0,this.index+1).filter(a=>a.ion)}}
if(typeof module!=='undefined'&&module.exports)module.exports={IonicRadius,ions};if(typeof document==='undefined')return;const root=document.getElementById('ionic-radius-game');if(!root)return;const game=new IonicRadius(),el=id=>document.getElementById('ir-'+id);
el('elements').innerHTML=ions.map((a,i)=>`<div class="ir-element${a.ion?'':' ir-no-ion'}" id="ir-element-${i}"><small>${a.z}</small><strong>${a.s}</strong><span>${a.ion||'—'}</span></div>`).join('');
function graph(){const x=i=>75+i*86,y=r=>235-(r-40)*1.35;let s='<title>Group against schematic ionic radius</title><desc>Cation radii decrease from sodium to aluminium. The radius rises on changing to phosphide, then decreases through sulfide, chloride and neutral argon.</desc><path d="M 65 35 V 245 H 705" class="ir-axis"/><text x="22" y="140" text-anchor="middle" transform="rotate(-90 22 140)" class="ir-axis-text">Relative radius</text><text x="380" y="302" text-anchor="middle" class="ir-axis-text">Group</text>';
 ions.forEach((a,i)=>{s+=`<line x1="${x(i)}" x2="${x(i)}" y1="245" y2="251" class="ir-axis"/><text x="${x(i)}" y="272" text-anchor="middle" class="ir-axis-text">${a.g}</text>`});
 const seen=ions.map((a,i)=>({...a,i})).filter(a=>a.i<=game.index&&a.ion);for(let i=1;i<seen.length;i++){const a=seen[i-1],b=seen[i];s+=`<line x1="${x(a.i)}" y1="${y(a.r)}" x2="${x(b.i)}" y2="${y(b.r)}" class="ir-graph-line${a.shells!==b.shells?' jump':''}"/>`}
 seen.forEach(a=>{s+=`<circle cx="${x(a.i)}" cy="${y(a.r)}" r="${a.i===game.index?7:5}" class="ir-point${a.shells===3?' anion':''}"/><text x="${x(a.i)}" y="${y(a.r)-15}" text-anchor="middle" class="ir-point-label">${a.ion}</text>`});el('graph').innerHTML=s;
}
function render(){const a=game.current;ions.forEach((_,i)=>{el('element-'+i).classList.toggle('active',i===game.index);if(i===game.index)el('element-'+i).setAttribute('aria-current','step');else el('element-'+i).removeAttribute('aria-current')});el('next').disabled=game.index===7;el('ion-title').textContent=a.ion||a.s;el('shell-diagram').hidden=!a.ion;el('no-ion').hidden=!!a.ion;el('no-ion').textContent=a.s==='Si'?'Silicon: no common simple monatomic ion shown.':'Argon: no common monatomic ion.';el('kind').textContent=a.ion?(a.neutral?'Neutral atom':a.shells===2?'Cation':'Anion'):'';el('shell-count').textContent=a.ion?a.shells+' shells · '+a.e+' electrons':'';
 for(let n=1;n<=3;n++){const c=el('shell-'+n);c.setAttribute('r',a.ion&&n<=a.shells?a.r*n/a.shells:0);c.style.opacity=a.ion&&n<=a.shells?'1':'0';c.classList.toggle('outer',n===a.shells)}el('protons').textContent=a.z+' p⁺';graph();
}
el('next').addEventListener('click',()=>{game.next();render();el('element-'+game.index).scrollIntoView({block:'nearest',inline:'nearest'})});el('reset').addEventListener('click',()=>{game.reset();render();el('element-0').scrollIntoView({block:'nearest',inline:'nearest'})});render();
})();
